#include <stdio.h>

int calculate_total(int unit_price, int quantity)
{
    return unit_price * quantity;
}

int main(void)
{
    const int price = 25;
    const int quantity = 4;
    const int total = calculate_total(price, quantity);
    printf("Total: %d\n", total);
    return 0;
}
